/// Une seule version : la couleur vient de `foregroundStyle` / `fill`.
struct LogoForme: Shape {
    static let largeur: CGFloat = 2601.2
    static let hauteur: CGFloat = 144.2

    func path(in rect: CGRect) -> Path {
        let k = min(rect.width / Self.largeur, rect.height / Self.hauteur)
        let ox = rect.minX + (rect.width - Self.largeur * k) / 2, oy = rect.minY + (rect.height - Self.hauteur * k) / 2
        func pt(_ i: Int) -> CGPoint { CGPoint(x: ox + CGFloat(Self.donnees[i]) * k, y: oy + CGFloat(Self.donnees[i + 1]) * k) }
        var p = Path()
        var i = 0
        while i < Self.donnees.count {
            switch Int(Self.donnees[i]) {
            case 0: p.move(to: pt(i + 1)); i += 3
            case 1: p.addLine(to: pt(i + 1)); i += 3
            case 2: p.addCurve(to: pt(i + 5), control1: pt(i + 1), control2: pt(i + 3)); i += 7
            default: p.closeSubpath(); i += 1
            }
        }
        return p
    }

